106	        LARGE_INTEGER li;
107	        li.QuadPart = 0;
108	        BOOL ret = SetFilePointerEx(fp_win32, li, &li, FILE_CURRENT);
109	        if (!ret) {
110	            throw std::runtime_error(format("read error: %s", GetErrorMessageWin32(GetLastError()).c_str()));
111	        }
112	
113	        return li.QuadPart;
114	    }
115	
116	    void seek(size_t offset, int whence) const {
117	        static_assert(SEEK_SET == FILE_BEGIN, "SEEK_SET != FILE_BEGIN");
118	        static_assert(SEEK_CUR == FILE_CURRENT, "SEEK_CUR != FILE_CURRENT");
119	        static_assert(SEEK_END == FILE_END, "SEEK_END != FILE_END");
120	
121	        LARGE_INTEGER li;
122	        li.QuadPart = offset;
123	        BOOL ret = SetFilePointerEx(fp_win32, li, NULL, whence);
124	        if (!ret) {
125	            throw std::runtime_error(format("read error: %s", GetErrorMessageWin32(GetLastError()).c_str()));
126	        }
127	    }
128	
129	    void read_raw(void * ptr, size_t len) {
130	        size_t bytes_read = 0;
131	        while (bytes_read < len) {
132	            size_t chunk_size = std::min<size_t>(len - bytes_read, 64*1024*1024);
133	            DWORD chunk_read = 0;
134	            BOOL result = ReadFile(fp_win32, reinterpret_cast<char*>(ptr) + bytes_read, chunk_size, &chunk_read, NULL);
135	            if (!result) {
136	                throw std::runtime_error(format("read error: %s", GetErrorMessageWin32(GetLastError()).c_str()));
137	            }
138	            if (chunk_read < chunk_size || chunk_read == 0) {
139	                throw std::runtime_error("unexpectedly reached end of file");
140	            }
141	
142	            bytes_read += chunk_read;
143	        }
144	    }
145	
146	    uint32_t read_u32() {
147	        uint32_t val;
148	        read_raw(&val, sizeof(val));
149	        return val;
150	    }
151	
152	    void write_raw(const void * ptr, size_t len) const {
153	        size_t bytes_written = 0;
154	        while (bytes_written < len) {
155	            size_t chunk_size = std::min<size_t>(len - bytes_written, 64*1024*1024);
156	            DWORD chunk_written = 0;
157	            BOOL result = WriteFile(fp_win32, reinterpret_cast<char const*>(ptr) + bytes_written, chunk_size, &chunk_written, NULL);
158	            if (!result) {
159	                throw std::runtime_error(format("write error: %s", GetErrorMessageWin32(GetLastError()).c_str()));
160	            }
161	            if (chunk_written < chunk_size || chunk_written == 0) {
162	                throw std::runtime_error("unexpectedly failed to write bytes");
163	            }
164	
165	            bytes_written += chunk_written;
166	        }
167	    }
168	
169	    void write_u32(uint32_t val) const {
170	        write_raw(&val, sizeof(val));
171	    }
