183	    impl(const char * fname, const char * mode, [[maybe_unused]] const bool use_direct_io = false) : fname(fname) {
184	#ifdef __linux__
185	        // Try unbuffered I/O for read only
186	        if (use_direct_io && std::strcmp(mode, "rb") == 0) {
