197	#ifdef __linux__
198	    bool init_fd() {
199	        fd = open(fname.c_str(), O_RDONLY | O_DIRECT);
200	
201	        if (fd != -1) {
202	            struct stat file_stats{};
203	            fstat(fd, &file_stats);
204	
205	            size = file_stats.st_size;
206	            alignment = file_stats.st_blksize;
207	
208	            off_t ret = lseek(fd, 0, SEEK_SET);
209	            if (ret == -1) {
210	                throw std::runtime_error(format("seek error: %s", strerror(errno)));
211	            }
212	            return true;
213	        }
214	        return false;
