218	    void init_fp(const char * mode) {
219	        fp = ggml_fopen(fname.c_str(), mode);
220	        if (fp == NULL) {
221	            throw std::runtime_error(format("failed to open %s: %s", fname.c_str(), strerror(errno)));
222	        }
223	        seek(0, SEEK_END);
224	        size = tell();
225	        seek(0, SEEK_SET);
