231	        size = tell();
232	        seek(0, SEEK_SET);
233	    }
234	
235	    size_t tell() const {
236	        if (fd == -1) {
237	            off_t ret = llama_mmap_ftell(fp);
238	            if (ret == -1) {
239	                throw std::runtime_error(format("ftell error: %s", strerror(errno)));
240	            }
241	
242	            return (size_t) ret;
243	        }
244	
245	        off_t pos = lseek(fd, 0, SEEK_CUR);
246	        if (pos == -1) {
247	            throw std::runtime_error(format("lseek error: %s", strerror(errno)));
248	        }
249	        return (size_t) pos;
250	    }
251	
252	    void seek(size_t offset, int whence) const {
253	        off_t ret = 0;
254	        if (fd == -1) {
255	            ret = llama_mmap_fseek(fp, offset, whence);
256	        } else {
257	            ret = lseek(fd, offset, whence);
258	        }
259	        if (ret == -1) {
260	            throw std::runtime_error(format("seek error: %s", strerror(errno)));
261	        }
262	    }
263	
264	    void read_raw_unsafe(void * ptr, size_t len) {
265	        if (len == 0) {
266	            return;
267	        }
268	        errno = 0;
269	        if (fd == -1) {
270	            const size_t curr_off = tell();
271	            const size_t to_read = std::min(len, size - curr_off);
272	
273	            std::size_t ret = std::fread(ptr, to_read, 1, fp);
274	            if (ferror(fp)) {
275	                throw std::runtime_error(format("read error: %s", strerror(errno)));
276	            }
277	            if (to_read > 0 && ret != 1) {
278	                throw std::runtime_error("unexpectedly reached end of file");
279	            }
280	        } else {
281	            size_t bytes_read = 0;
282	            while (bytes_read < len) {
283	                const size_t to_read = len - bytes_read;
284	                ssize_t ret = ::read(fd, reinterpret_cast<char *>(ptr) + bytes_read, to_read);
285	
286	                if (ret == -1) {
287	                    if (errno == EINTR) {
288	                        continue;  // Interrupted by signal, retry
289	                    }
290	                    // Fallback to std::fread in case the DMA controller cannot access the buffer
291	                    if (errno == EFAULT || errno == EINVAL) {
292	                        LLAMA_LOG_WARN("%s: Falling back to buffered IO due to %s\n", __func__, strerror(errno));
293	                        auto curr_off = tell();
294	                        close(fd);
295	                        fd = -1;
296	                        alignment = 1;
297	                        init_fp("rb");
298	                        seek(curr_off, SEEK_SET);
299	                        read_raw_unsafe(ptr, len);
300	                        return;
301	                    }
302	                    throw std::runtime_error(format("read error: %s", strerror(errno)));
303	                }
304	                if (ret == 0) {
305	                    // EOF: allow if this read was only pulling alignment padding past file end
306	                    off_t pos = lseek(fd, 0, SEEK_CUR);
307	                    if (pos != -1 && (size_t) pos == size) {
308	                        std::memset(reinterpret_cast<char *>(ptr) + bytes_read, 0, len - bytes_read);
309	                        return;
310	                    }
311	                    throw std::runtime_error("unexpectedly reached end of file");
312	                }
313	
314	                bytes_read += (size_t) ret;
315	            }
316	        }
317	    }
318	
319	    void read_aligned_chunk(void * dest, size_t size) {
320	        size_t offset = tell();
321	        off_t aligned_offset = offset & ~(alignment - 1);
322	        off_t offset_from_alignment = offset - aligned_offset;
323	        size_t bytes_to_read = (offset_from_alignment + size + alignment - 1) & ~(alignment - 1);
324	
325	        void * raw_buffer = nullptr;
326	        int ret = posix_memalign(&raw_buffer, alignment, bytes_to_read);
327	        if (ret != 0) {
328	            throw std::runtime_error(format("posix_memalign failed with error %d", ret));
329	        }
330	
331	        struct aligned_buffer_deleter {
332	            void operator()(void * p) const { free(p); }
333	        };
334	        std::unique_ptr<void, aligned_buffer_deleter> buffer(raw_buffer);
335	
336	        seek(aligned_offset, SEEK_SET);
337	        read_raw_unsafe(buffer.get(), bytes_to_read);
338	
339	        uintptr_t actual_data = reinterpret_cast<uintptr_t>(buffer.get()) + offset_from_alignment;
340	        memcpy(dest, reinterpret_cast<void *>(actual_data), size);
341	    }
342	
343	    void read_raw(void * ptr, size_t len) {
344	        if (has_direct_io()) {
345	            read_aligned_chunk(ptr, len);
346	        } else {
347	            read_raw_unsafe(ptr, len);
348	        }
349	    }
350	
351	    uint32_t read_u32() {
352	        uint32_t ret;
353	        read_raw(&ret, sizeof(ret));
354	        return ret;
355	    }
356	
357	    void write_raw(const void * ptr, size_t len) const {
358	        if (len == 0) {
359	            return;
360	        }
361	        errno = 0;
362	        size_t ret = std::fwrite(ptr, len, 1, fp);
363	        if (ret != 1) {
364	            throw std::runtime_error(format("write error: %s", strerror(errno)));
365	        }
366	    }
367	
368	    void write_u32(uint32_t val) const {
369	        write_raw(&val, sizeof(val));
370	    }
371	
372	    bool has_direct_io() const {
373	        return fd != -1 && alignment > 1;
374	    }
375	
376	    ~impl() {
377	        if (fd != -1) {
378	            close(fd);
379	        } else if (owns_fp) {
380	            std::fclose(fp);
381	        }
382	    }
383	    int fd = -1;
384	    std::string fname;
385	#endif
386	
387	    size_t read_alignment() const {
388	        return alignment;
389	    }
390	
391	    size_t alignment = 1;
392	
393	    FILE * fp{};
394	    size_t size{};
395	    bool owns_fp = true;
396	};
