441	struct llama_mmap::impl {
442	#ifdef _POSIX_MAPPED_FILES
443	    std::vector<std::pair<size_t, size_t>> mapped_fragments;
444	
445	    impl(struct llama_file * file, size_t prefetch, bool numa) {
446	        size = file->size();
447	        int fd = file->file_id();
448	        int flags = MAP_SHARED;
449	        if (numa) { prefetch = 0; }
450	#ifdef __linux__
451	        if (posix_fadvise(fd, 0, 0, POSIX_FADV_SEQUENTIAL)) {
452	            LLAMA_LOG_WARN("warning: posix_fadvise(.., POSIX_FADV_SEQUENTIAL) failed: %s\n",
453	                    strerror(errno));
454	        }
455	        if (prefetch) { flags |= MAP_POPULATE; }
456	#endif
457	        addr = mmap(NULL, file->size(), PROT_READ, flags, fd, 0);
458	        if (addr == MAP_FAILED) {
459	            throw std::runtime_error(format("mmap failed: %s", strerror(errno)));
460	        }
461	
462	        if (prefetch > 0) {
463	            if (posix_madvise(addr, std::min(file->size(), prefetch), POSIX_MADV_WILLNEED)) {
464	                LLAMA_LOG_WARN("warning: posix_madvise(.., POSIX_MADV_WILLNEED) failed: %s\n",
465	                        strerror(errno));
466	            }
467	        }
468	        if (numa) {
469	            if (posix_madvise(addr, file->size(), POSIX_MADV_RANDOM)) {
470	                LLAMA_LOG_WARN("warning: posix_madvise(.., POSIX_MADV_RANDOM) failed: %s\n",
471	                        strerror(errno));
472	            }
473	        }
474	
475	        mapped_fragments.emplace_back(0, file->size());
476	    }
477	
478	    static void align_range(size_t * first, size_t * last, size_t page_size) {
479	        size_t offset_in_page = *first & (page_size - 1);
480	        size_t offset_to_page = offset_in_page == 0 ? 0 : page_size - offset_in_page;
481	        *first += offset_to_page;
482	
483	        *last = *last & ~(page_size - 1);
484	
485	        if (*last <= *first) {
486	            *last = *first;
487	        }
488	    }
489	
490	    void unmap_fragment(size_t first, size_t last) {
491	        int page_size = sysconf(_SC_PAGESIZE);
492	        align_range(&first, &last, page_size);
493	        size_t len = last - first;
494	
495	        if (len == 0) {
496	            return;
497	        }
498	
499	        GGML_ASSERT(first % page_size == 0);
500	        GGML_ASSERT(last % page_size == 0);
501	        GGML_ASSERT(last > first);
502	
503	        void * next_page_start = (uint8_t *) addr + first;
504	
505	        if (munmap(next_page_start, len)) {
506	            LLAMA_LOG_WARN("warning: munmap failed: %s\n", strerror(errno));
507	        }
508	
509	        std::vector<std::pair<size_t, size_t>> new_mapped_fragments;
510	        for (const auto & frag : mapped_fragments) {
511	            if (frag.first < first && frag.second > last) {
512	                new_mapped_fragments.emplace_back(frag.first, first);
513	                new_mapped_fragments.emplace_back(last, frag.second);
514	            } else if (frag.first < first && frag.second > first) {
515	                new_mapped_fragments.emplace_back(frag.first, first);
516	            } else if (frag.first < last && frag.second > last) {
517	                new_mapped_fragments.emplace_back(last, frag.second);
518	            } else if (frag.first >= first && frag.second <= last) {
519	            } else {
520	                new_mapped_fragments.push_back(frag);
521	            }
522	        }
523	        mapped_fragments = std::move(new_mapped_fragments);
524	    }
525	
526	    ~impl() {
527	        for (const auto & frag : mapped_fragments) {
528	            if (munmap((char *) addr + frag.first, frag.second - frag.first)) {
529	                LLAMA_LOG_WARN("warning: munmap failed: %s\n", strerror(errno));
530	            }
531	        }
532	    }
533	#elif defined(_WIN32)
534	    HANDLE hMapping = nullptr;
535	
536	    impl(struct llama_file * file, size_t prefetch, bool numa) {
537	        GGML_UNUSED(numa);
538	
539	        size = file->size();
540	
541	        HANDLE hFile = (HANDLE) _get_osfhandle(file->file_id());
542	
543	        hMapping = CreateFileMappingA(hFile, NULL, PAGE_READONLY, 0, 0, NULL);
544	
545	        if (hMapping == NULL) {
546	            DWORD error = GetLastError();
547	            throw std::runtime_error(format("CreateFileMappingA failed: %s", llama_format_win_err(error).c_str()));
548	        }
549	
550	        addr = MapViewOfFile(hMapping, FILE_MAP_READ, 0, 0, 0);
551	        DWORD error = GetLastError();
552	
553	        if (addr == NULL) {
554	            CloseHandle(hMapping);
555	            throw std::runtime_error(format("MapViewOfFile failed: %s", llama_format_win_err(error).c_str()));
556	        }
557	
558	        if (prefetch > 0) {
559	#if _WIN32_WINNT >= 0x602
560	            BOOL (WINAPI *pPrefetchVirtualMemory) (HANDLE, ULONG_PTR, PWIN32_MEMORY_RANGE_ENTRY, ULONG);
561	            HMODULE hKernel32 = GetModuleHandleW(L"kernel32.dll");
562	
563	            pPrefetchVirtualMemory = (decltype(pPrefetchVirtualMemory))(void *) GetProcAddress(hKernel32, "PrefetchVirtualMemory");
564	
565	            if (pPrefetchVirtualMemory) {
566	                WIN32_MEMORY_RANGE_ENTRY range;
567	                range.VirtualAddress = addr;
568	                range.NumberOfBytes = (SIZE_T) std::min(size, prefetch);
569	                if (!pPrefetchVirtualMemory(GetCurrentProcess(), 1, &range, 0)) {
570	                    LLAMA_LOG_WARN("warning: PrefetchVirtualMemory failed: %s\n",
571	                            llama_format_win_err(GetLastError()).c_str());
572	                }
573	            }
574	#else
575	            LLAMA_LOG_DEBUG("skipping PrefetchVirtualMemory because _WIN32_WINNT < 0x602\n");
576	#endif
577	        }
578	    }
579	
580	    void unmap_fragment(size_t first, size_t last) {
581	        GGML_UNUSED(first);
582	        GGML_UNUSED(last);
583	    }
584	
585	    ~impl() {
586	        if (hMapping) {
587	            if (addr) {
588	                if (!UnmapViewOfFile(addr)) {
589	                    LLAMA_LOG_WARN("warning: UnmapViewOfFile failed: %s\n",
590	                            llama_format_win_err(GetLastError()).c_str());
591	                }
592	            }
593	            if (!CloseHandle(hMapping)) {
594	                LLAMA_LOG_WARN("warning: CloseHandle failed: %s\n",
595	                        llama_format_win_err(GetLastError()).c_str());
596	            }
597	        }
598	    }
599	#else
600	    impl(struct llama_file * file, size_t prefetch, bool numa) {
601	        GGML_UNUSED(file);
602	        GGML_UNUSED(prefetch);
603	        GGML_UNUSED(numa);
604	
605	        throw std::runtime_error("mmap not supported");
606	    }
607	
608	    void unmap_fragment(size_t first, size_t last) {
609	        GGML_UNUSED(first);
610	        GGML_UNUSED(last);
611	
612	        throw std::runtime_error("mmap not supported");
613	    }
614	#endif
615	
616	    void * addr;
617	    size_t size;
618	};
