636	struct llama_mlock::impl {
637	#ifdef _POSIX_MEMLOCK_RANGE
638	    static size_t lock_granularity() {
639	        return (size_t) sysconf(_SC_PAGESIZE);
640	    }
641	
642	    bool raw_lock(const void * addr, size_t size) const {
643	        if (!mlock(addr, size)) {
644	            return true;
645	        }
646	
647	#ifdef __APPLE__
648	#define MLOCK_SUGGESTION \
649	        "Try increasing the sysctl values 'vm.user_wire_limit' and 'vm.global_user_wire_limit' and/or " \
650	        "decreasing 'vm.global_no_user_wire_amount'.  Also try increasing RLIMIT_MEMLOCK (ulimit -l).\n"
651	#else
652	#define MLOCK_SUGGESTION \
653	        "Try increasing RLIMIT_MEMLOCK ('ulimit -l' as root).\n"
654	#endif
655	
656	        char* errmsg = std::strerror(errno);
657	        bool suggest = (errno == ENOMEM);
658	#if defined(TARGET_OS_VISION) || defined(TARGET_OS_TV) || defined(_AIX) || defined(__HAIKU__)
659	        // visionOS/tvOS/Haiku don't support RLIMIT_MEMLOCK
660	        // Skip resource limit checks on these platforms
661	        suggest = false;
662	#else
663	        struct rlimit lock_limit;
664	        if (suggest && getrlimit(RLIMIT_MEMLOCK, &lock_limit)) {
665	            suggest = false;
666	        }
667	        if (suggest && ((uint64_t)lock_limit.rlim_max > (uint64_t)lock_limit.rlim_cur + size)) {
668	            suggest = false;
669	        }
670	#endif
671	
672	        LLAMA_LOG_WARN("warning: failed to mlock %zu-byte buffer (after previously locking %zu bytes): %s\n%s",
673	                size, this->size, errmsg, suggest ? MLOCK_SUGGESTION : "");
674	        return false;
675	    }
676	
677	    static void raw_unlock(void * addr, size_t size) {
678	        if (munlock(addr, size)) {
679	            LLAMA_LOG_WARN("warning: failed to munlock buffer: %s\n", std::strerror(errno));
680	        }
681	    }
682	#elif defined(_WIN32)
683	    static size_t lock_granularity() {
684	        SYSTEM_INFO si;
685	        GetSystemInfo(&si);
686	        return (size_t) si.dwPageSize;
687	    }
688	
689	    bool raw_lock(void * ptr, size_t len) const {
690	        for (int tries = 1; ; tries++) {
691	            if (VirtualLock(ptr, len)) {
692	                return true;
693	            }
694	            if (tries == 2) {
695	                LLAMA_LOG_WARN("warning: failed to VirtualLock %zu-byte buffer (after previously locking %zu bytes): %s\n",
696	                    len, size, llama_format_win_err(GetLastError()).c_str());
697	                return false;
698	            }
699	
700	            SIZE_T min_ws_size, max_ws_size;
701	            if (!GetProcessWorkingSetSize(GetCurrentProcess(), &min_ws_size, &max_ws_size)) {
702	                LLAMA_LOG_WARN("warning: GetProcessWorkingSetSize failed: %s\n",
703	                        llama_format_win_err(GetLastError()).c_str());
704	                return false;
705	            }
706	            size_t increment = len + 1048576;
707	            min_ws_size += increment;
708	            max_ws_size += increment;
709	            if (!SetProcessWorkingSetSize(GetCurrentProcess(), min_ws_size, max_ws_size)) {
710	                LLAMA_LOG_WARN("warning: SetProcessWorkingSetSize failed: %s\n",
711	                        llama_format_win_err(GetLastError()).c_str());
712	                return false;
713	            }
714	        }
715	    }
716	
717	    static void raw_unlock(void * ptr, size_t len) {
718	        if (!VirtualUnlock(ptr, len)) {
719	            LLAMA_LOG_WARN("warning: failed to VirtualUnlock buffer: %s\n",
720	                    llama_format_win_err(GetLastError()).c_str());
721	        }
722	    }
723	#else
724	    static size_t lock_granularity() {
725	        return (size_t) 65536;
726	    }
