743	    void grow_to(size_t target_size) {
744	        GGML_ASSERT(addr);
745	        if (failed_already) {
746	            return;
747	        }
748	        size_t granularity = lock_granularity();
749	        target_size = (target_size + granularity - 1) & ~(granularity - 1);
750	        if (target_size > size) {
751	            if (raw_lock((uint8_t *) addr + size, target_size - size)) {
752	                size = target_size;
753	            } else {
754	                failed_already = true;
755	            }
756	        }
